import { randomUUID } from 'node:crypto';

import {
  ATTACHMENT_MIME_TO_EXTENSION,
  type AllowedAttachmentMimeType,
} from '@pulse-chat/shared';

/** Storage keys generated by the server: `<uuid>.<detected-extension>`. */
export const STORAGE_KEY_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|gif|webp|pdf|txt)$/;

/** Builds a collision-resistant storage key from a server-detected MIME type. */
export function generateStorageKey(mimeType: AllowedAttachmentMimeType): string {
  const extension = ATTACHMENT_MIME_TO_EXTENSION[mimeType];
  return `${randomUUID()}.${extension}`;
}
